{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Mesenchymal stem/stromal cells (MSCs) and their secreted products are a promising therapy for COVID-19 given their immunomodulatory and tissue repair capabilities. Many small studies were launched at the onset of the pandemic",
      "reason": "The abstract background indicates current knowledge (promising therapy, many small studies) and implies uncertainty about efficacy, but the full Introduction section with a detailed account of existing knowledge and uncertainties was not retrieved."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "repeated meta-analysis is critical to obtain timely and sufficient statistical power to determine efficacy",
      "reason": "The need for the review is explicitly stated: repeated meta-analysis is needed for timely, adequately powered estimation of efficacy."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": "text_26",
      "quote": "many registered clinical trials dealing with the use of MSC-based products as a therapeutic intervention for COVID-19 were identified in a scoping review performed by our group [31]",
      "reason": "Although described as the first iteration of a living review and a prior scoping review is mentioned, the manuscript does not explicitly discuss or cite previous similar systematic reviews to justify the need for this review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "text_26",
      "quote": "Thus, the pleiotropic anti-inflammatory and regenerative effects of MSCs may point to several potential mechanisms by which MSCs exert their apparent beneficial effect.",
      "reason": "Mechanisms of action (immunomodulation via cytokine modulation, macrophage repolarization, tissue regeneration; see also Table 7) are described in detail."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model showing hypothesised relationships between intervention components and outcomes is reported; only a narrative mechanism table is provided."
    }
  ],
  "confidence": 70
}

{
