      "reason": "No additional random-effects implementation details are provided beyond the named model."
    },
    {
      "element_id": "prisma_2020_13d_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "A frequentist (RevMan, DerSimonian-Laird) meta-analysis was performed; no Bayesian analysis, so priors do not apply."
